#include <vector>

class Solution {
public:
    std::vector<int> findVertexDegrees(int n, std::vector<std::vector<int>>& edges) {
        std::vector<int> deg(n, 0);
        for (const auto& e : edges) {
            deg[e[0]]++;
            deg[e[1]]++;
        }
        return deg;
    }
};

class Solution {
    public int[] findVertexDegrees(int n, int[][] edges) {
        int[] deg = new int[n];
        for (int[] e : edges) {
            deg[e[0]]++;
            deg[e[1]]++;
        }
        return deg;
    }
}

